"use client"

import * as React from "react"

import { Input } from "@/components/ui/field"
import { cn } from "@/lib/utils"

function findTextMatches(text: string, query: string): { start: number; end: number }[] {
  if (!query) return []
  const escaped = query.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")
  return [...text.matchAll(new RegExp(escaped, "giu"))].map((m) => ({ start: m.index, end: m.index + m[0].length }))
}

type TextSearchProps = Omit<React.ComponentProps<"section">, "children"> & {
  text: string
  label?: string
  query?: string
  defaultQuery?: string
  onQueryChange?: (query: string) => void
  previousLabel?: string
  nextLabel?: string
  countLabel?: (current: number, total: number) => string
}

/** Find within the supplied passage, rather than filtering away its context. */
function TextSearch({ text, label = "Find in this passage", query: controlled, defaultQuery = "", onQueryChange, previousLabel = "Previous", nextLabel = "Next", countLabel = (current, total) => `${current} of ${total} matches`, className, ...props }: TextSearchProps) {
  const id = React.useId()
  const [local, setLocal] = React.useState(defaultQuery)
  const query = controlled ?? local
  const matches = React.useMemo(() => findTextMatches(text, query), [text, query])
  const [position, setPosition] = React.useState({ text, query, index: 0 })
  if (position.text !== text || position.query !== query) setPosition({ text, query, index: 0 })
  const index = position.text === text && position.query === query ? Math.min(position.index, Math.max(0, matches.length - 1)) : 0
  const marks = React.useRef<(HTMLElement | null)[]>([])
  const reading = React.useRef<HTMLDivElement>(null)
  const coordinate = React.useRef<HTMLSpanElement>(null)
  const [located, setLocated] = React.useState(false)
  React.useLayoutEffect(() => {
    const place = () => {
      const mark = marks.current[index]
      if (reading.current && coordinate.current && mark) {
        const y = mark.getBoundingClientRect().top - reading.current.getBoundingClientRect().top
        coordinate.current.style.setProperty("--db-search-y", `${y}px`)
      }
    }
    place()
    const observer = new ResizeObserver(place)
    if (reading.current) observer.observe(reading.current)
    return () => observer.disconnect()
  }, [index, text, query])
  const move = (delta: number) => {
    if (!matches.length) return
    setLocated(true)
    const next = (index + delta + matches.length) % matches.length
    setPosition({ text, query, index: next })
    // Navigation is deliberate; typing never scrolls or steals focus.
    marks.current[next]?.scrollIntoView({ block: "nearest", behavior: "instant" })
  }
  const chunks: React.ReactNode[] = []
  let end = 0
  matches.forEach((m, i) => {
    chunks.push(text.slice(end, m.start))
    chunks.push(<mark key={m.start} ref={(el) => { marks.current[i] = el }} data-slot="text-search-match" data-current={i === index ? "" : undefined}>{text.slice(m.start, m.end)}</mark>)
    end = m.end
  })
  chunks.push(text.slice(end))
  return <section {...props} data-slot="text-search" data-located={located ? "" : undefined} className={cn("db-text-search", className)} aria-label={props["aria-label"] ?? label}>
    <label data-slot="text-search-label" className="db-label" htmlFor={id}>{label}</label>
    <Input type="search" id={id} data-slot="text-search-input" value={query} aria-describedby={`${id}-count`} onChange={(e) => { setLocated(true); if (controlled === undefined) setLocal(e.target.value); onQueryChange?.(e.target.value) }} onKeyDown={(e) => { if (e.key === "Enter" && !e.nativeEvent.isComposing) { e.preventDefault(); move(e.shiftKey ? -1 : 1) } }} />
    <div className="db-text-search-tools">
      <span id={`${id}-count`} role="status" aria-atomic="true">{countLabel(matches.length ? index + 1 : 0, matches.length)}</span>
      <button type="button" disabled={!matches.length} onClick={() => move(-1)}>{previousLabel}</button>
      <button type="button" disabled={!matches.length} onClick={() => move(1)}>{nextLabel}</button>
    </div>
    <div className="db-text-search-reading" ref={reading}>
      {matches.length ? <span ref={coordinate} className="db-text-search-coordinate" aria-hidden="true">{String(index + 1).padStart(2, "0")}</span> : null}
      <p data-slot="text-search-passage" className="db-text-search-passage">{chunks}</p>
    </div>
  </section>
}

export { TextSearch, findTextMatches, type TextSearchProps }

@layer components {
  /* Weingart's callout becomes a travelling line coordinate, while the actual passage keeps its setting. */
  .db-text-search { min-inline-size: 0; overflow-wrap: anywhere; container-type: inline-size; }
  .db-text-search > .db-input { display: block; inline-size: 100%; font-size: clamp(2.5rem, 11cqi, 5rem); font-family: var(--db-expression); font-style: italic; line-height: 1.2; letter-spacing: -0.04em; margin-block: var(--db-space-2); padding-block: var(--db-space-3); }
  .db-text-search-tools { display: flex; flex-wrap: wrap; align-items: baseline; gap: var(--db-space-4); font-size: var(--db-pp); margin-block: var(--db-space-2) var(--db-space-6); }
  .db-text-search-tools > span { margin-inline-end: auto; color: var(--db-pencil); }
  .db-text-search-tools > button { border: 0; background: none; min-block-size: 44px; padding: var(--db-space-3) 0; cursor: pointer; text-decoration: underline; text-underline-offset: 0.3em; }
  .db-text-search-tools > button:disabled { color: var(--db-pencil); cursor: default; text-decoration: none; }
  .db-text-search-reading { position: relative; padding-inline-start: 3.7rem; }
  .db-text-search-coordinate { position: absolute; inset-inline-start: 0; inset-block-start: 0; font-size: 1.7rem; font-weight: 300; letter-spacing: -0.06em; line-height: 1; color: var(--db-pencil); transform: translateY(var(--db-search-y, 0px)); transition: transform var(--db-andante) var(--db-spiccato); }
  .db-text-search-coordinate::after { content: ""; display: block; inline-size: 2rem; border-block-start: var(--db-hairline) solid var(--db-rule-strong); margin-block-start: var(--db-space-2); }
  .db-text-search-passage { white-space: pre-wrap; font-size: clamp(1.2rem, 4.5cqi, 1.65rem); font-weight: 300; line-height: 1.65; max-inline-size: var(--db-measure); }
  .db-text-search mark { position: relative; background: none; color: inherit; text-decoration: underline; text-decoration-color: var(--db-rule-strong); text-decoration-thickness: var(--db-hairline); text-underline-offset: 0.2em; }
  .db-text-search mark[data-current] { text-decoration-color: var(--db-accent); text-decoration-thickness: var(--db-stroke); }
  .db-text-search[data-located] mark[data-current]::before { content: "(" / ""; position: absolute; inset-inline-start: -0.22em; color: var(--db-accent); font-family: var(--db-expression); transform: translateX(-0.18em); animation: db-search-clasp var(--db-andante) var(--db-spiccato) both; }
  .db-text-search[data-located] mark[data-current]::after { content: ")" / ""; position: absolute; inset-inline-end: -0.22em; color: var(--db-accent); font-family: var(--db-expression); transform: translateX(0.18em); animation: db-search-clasp var(--db-andante) var(--db-spiccato) both; }
  @keyframes db-search-clasp { from { translate: 0 -0.25em; scale: 1 1.8; opacity: 0; } to { translate: 0 0; scale: 1 1; opacity: 1; } }
  @media (prefers-reduced-motion: reduce) { .db-text-search-coordinate, .db-text-search mark::before, .db-text-search mark::after { transition: none; animation: none; } }
  @media (forced-colors: active) { .db-text-search mark { color: CanvasText; background: transparent; } .db-text-search mark[data-current] { outline: var(--db-hairline) solid Highlight; text-decoration-color: Highlight; } }
}
